import React from "react";
import Nav from "./nav";
import LandingPage from "./landingPage";
import Passions from "./passions";

export default function Home(){
    return(
        <div className="w-full h-[100vh] poppins">
            <Nav />
            <div className="flex flex-row">
                <div className="w-[50%]">
                <div className=" w-[100%] z-10 h-[100vh] flex flex-row items-center justify-center bg-no-repeat bg-contain" style={{ backgroundImage: "url('/landingPage/lpImage.jpeg')" }}></div>
                </div>
                <div className="flex flex-col over">
                    <LandingPage />
                    <Passions />
                </div>
            </div>

        </div>
    )
}
